sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    var getNumberPhone = new GlideAjax("GetPhoneNumber"); //Nombre del ScriptInclude
    getNumberPhone.addParam('sysparm_name', 'getPhone'); //Nombre del método a usar en ScriptInclude
    getNumberPhone.addParam('sysparm_UserId', g_form.getValue('u_requested_for'));
	getNumberPhone.getXML(completePhoneField); //La respuetsa del servidor pásala a la función para procesarla.

	function completePhoneField(response) { //La función siempre recibe un objeto response
		var answer = response.responseXML.documentElement.getAttribute("answer");
		g_form.setValue('u_requested_for_phone', answer);

	} 
}
